import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"用主题自定义 Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/themes.md","filePath":"zh/themes.md"}'),s={name:"zh/themes.md"};function c(i,t,r,h,l,n){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="用主题自定义-pi" tabindex="-1">用主题自定义 Pi <a class="header-anchor" href="#用主题自定义-pi" aria-label="Permalink to &quot;用主题自定义 Pi&quot;">​</a></h1><p>主题控制 Pi 在交互模式和 HTML 导出中使用的颜色。Pi 内置 <code>system</code>、<code>dark</code> 和 <code>light</code> 主题。你可以选择其中一个主题、跟随终端的浅色或深色外观，或创建自己的配色。</p><h2 id="使用终端的颜色" tabindex="-1">使用终端的颜色 <a class="header-anchor" href="#使用终端的颜色" aria-label="Permalink to &quot;使用终端的颜色&quot;">​</a></h2><p><code>system</code> 主题是默认主题。它基于终端的主题构建 Pi 的颜色，让 Pi 与终端保持一致，而不是自带配色：</p><ul><li>Pi 查询终端的默认前景色、背景色及其 16 个 ANSI 颜色。</li><li>每个 Pi 颜色的色相取自某个 ANSI 颜色，例如错误取红色、链接取蓝色。</li><li>Pi 调整每个颜色的明度，使其与背景保持最低对比度。正文文本在背景和每个面板上至少保持 4.5:1 的 WCAG 对比度。</li><li>当终端在浅色和深色之间切换时，Pi 会重新查询颜色并重建主题。</li></ul><p>主题会根据终端上报的内容进行适配：</p><table tabindex="0"><thead><tr><th>终端上报内容</th><th>结果</th></tr></thead><tbody><tr><td>背景色和 ANSI 颜色</td><td>来自终端调色板、并针对实际背景放置的颜色。</td></tr><tr><td>仅背景色</td><td>Pi 自身的色相，并针对实际背景放置。</td></tr><tr><td>无</td><td>ANSI 颜色索引和终端默认颜色，由终端自行渲染。次要文本较淡，面板无背景色。</td></tr></tbody></table><p>Pi 在启动时向终端询问颜色。终端通常在几毫秒内应答，Pi 最多等待 100 毫秒后显示启动页眉。如果终端未及时应答，Pi 使用 ANSI 颜色回退；如果颜色稍后到达（例如通过慢速 SSH 连接），Pi 仍会应用它们。<code>system</code> 是保留名称：使用该名称的自定义主题会被忽略。</p><p><a id="selecting-a-theme"></a></p><h2 id="选择主题" tabindex="-1">选择主题 <a class="header-anchor" href="#选择主题" aria-label="Permalink to &quot;选择主题&quot;">​</a></h2><p>打开 <code>/settings</code> 并选择 <strong>Theme</strong>。你可以为所有终端外观使用同一个主题，也可以为浅色和深色终端分别选择主题。</p><p>所选内容保存为 <code>theme</code> <a href="./settings.html#terminal-and-display">设置</a>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>没有 <code>theme</code> 设置时，Pi 使用 <code>system</code>。</p><p>自动模式按先浅色、后深色的顺序存储：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;light/dark&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pi 根据终端上报的背景色和前景色判断终端是浅色还是深色。如果终端不上报背景色，Pi 依次使用终端的浅色/深色通知、<code>COLORFGBG</code> 环境变量，最后默认深色。同一判断既决定浅色/深色对中选用哪个主题，也决定 <code>system</code> 的外观。自动模式激活时，终端上报外观变化后 Pi 会切换主题。主题名称不能包含 <code>/</code>，因为 Pi 将其保留用于该设置的格式。</p><p>使用 <code>--use-theme</code> 在单次运行中选择初始主题，而不更改保存的设置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use-theme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> light</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --use-theme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> light/dark</span></span></code></pre></div><p>命令行选项见 <a href="./cli.html#resources">CLI 资源</a>。</p><h2 id="创建自定义主题" tabindex="-1">创建自定义主题 <a class="header-anchor" href="#创建自定义主题" aria-label="Permalink to &quot;创建自定义主题&quot;">​</a></h2><p>复制一个<a href="https://github.com/earendil-works/pi/tree/main/packages/coding-agent/src/modes/interactive/theme" target="_blank" rel="noreferrer">内置主题</a>，或创建一个符合<a href="https://pi.dev/schemas/theme.schema.json" target="_blank" rel="noreferrer">模式（schema）</a>的新 JSON 文件。内置主题使用 OKHSL 颜色，多个角色共享的颜色用变量表示，因此你可以直接调整色相、饱和度或明度。</p><ol><li>将文件保存为 <code>&lt;agent-dir&gt;/themes/my-theme.json</code>。agent 目录默认为 <code>~/.pi/agent</code>。</li><li>将其 <code>name</code> 设为 <code>my-theme</code>。</li><li>修改 <code>vars</code> 和 <code>colors</code> 中的值。</li><li>通过 <code>/settings</code> 选择 <code>my-theme</code>。</li></ol><p>文件名使用主题名称。Pi 仅从 <code>&lt;agent-dir&gt;/themes/&lt;name&gt;.json</code> 热重载当前生效的用户主题。从其他来源添加或修改主题后，运行 <code>/reload</code>。</p><h2 id="理解主题文件" tabindex="-1">理解主题文件 <a class="header-anchor" href="#理解主题文件" aria-label="Permalink to &quot;理解主题文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>必需</th><th>职责</th></tr></thead><tbody><tr><td><code>$schema</code></td><td>否</td><td>根据 Pi 发布的 schema 启用编辑器校验和补全。</td></tr><tr><td><code>name</code></td><td>是</td><td>在选择器和设置中标识主题。必须唯一，不能包含 <code>/</code>，也不能是 <code>system</code>。</td></tr><tr><td><code>appearance</code></td><td>否</td><td><code>&quot;dark&quot;</code> 或 <code>&quot;light&quot;</code>：主题设计的背景。省略时 Pi 从主题颜色推断。</td></tr><tr><td><code>vars</code></td><td>否</td><td>定义可复用的颜色值。变量可以引用其他变量。</td></tr><tr><td><code>colors</code></td><td>是</td><td>为终端 UI 角色分配颜色。schema 标明必需和可选角色。</td></tr><tr><td><code>export</code></td><td>否</td><td>覆盖 HTML 导出中的页面和面板背景。</td></tr></tbody></table><p>主题对象是严格的：只接受文档中列出的顶层字段和颜色令牌（token）。可复用的自定义颜色定义在 <code>vars</code> 下；<code>colors</code> 或 <code>export</code> 下的自定义键以及其他顶层元数据会被拒绝。</p><p>颜色可以用六种形式书写：</p><table tabindex="0"><thead><tr><th>形式</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td>RGB 十六进制</td><td><code>&quot;#0af&quot;</code> 或 <code>&quot;#00aaff&quot;</code></td><td>三位或六位 sRGB 颜色。</td></tr><tr><td>OKLCH</td><td><code>&quot;oklch(62% 0.1 200)&quot;</code></td><td>感知明度、彩度和色相。</td></tr><tr><td>OKHSL</td><td><code>&quot;okhsl(250 60% 55%)&quot;</code></td><td>色相、饱和度和明度。饱和度相对于 sRGB 色域在该色相和明度下允许的最大值，因此每个值都在色域内，相同的饱和度看起来色彩程度相同。</td></tr><tr><td>256 色索引</td><td><code>39</code></td><td><code>0</code> 到 <code>255</code> 的 ANSI 调色板索引。</td></tr><tr><td>变量引用</td><td><code>&quot;primary&quot;</code></td><td><code>vars</code> 中某个条目的值。</td></tr><tr><td>终端默认</td><td><code>&quot;&quot;</code></td><td>终端的默认前景色或背景色。</td></tr></tbody></table><p>终端默认颜色按终端自身的颜色渲染。当 Pi 需要具体值时（例如 HTML 导出或扩展的颜色计算），它使用终端上报的默认颜色，或根据主题外观猜测黑或白。</p><p>Pi 解析链式变量引用。缺失变量或循环引用会使主题无效。Pi 在可用时使用真彩色（truecolor），将 OKLCH 色域映射（gamut-map）到 sRGB，并为 256 色终端近似颜色。HTML 导出将 OKHSL 值转换为十六进制，因为 CSS 不支持它们。如果颜色与来源值不同，检查终端的真彩色检测和对比度设置。见<a href="./terminal-setup.html#override-detected-capabilities">配置终端</a>。</p><p>确切的属性、必需颜色和接受的值类型见<a href="https://pi.dev/schemas/theme.schema.json" target="_blank" rel="noreferrer">主题 JSON schema</a>。</p><p>Pi 在启动时和 <code>/reload</code> 时报告无效的主题文件。</p><h2 id="找到要修改的颜色" tabindex="-1">找到要修改的颜色 <a class="header-anchor" href="#找到要修改的颜色" aria-label="Permalink to &quot;找到要修改的颜色&quot;">​</a></h2><p>主题颜色描述的是界面角色，而不是单个组件。使用以下分组找到 schema 中的相关部分：</p><table tabindex="0"><thead><tr><th>区域</th><th>颜色名称</th></tr></thead><tbody><tr><td>通用界面</td><td><code>accent</code>, <code>border*</code>, <code>text</code>, <code>muted</code>, <code>dim</code>, <code>success</code>, <code>error</code>, <code>warning</code></td></tr><tr><td>选择与全屏</td><td><code>selectedBg</code>, <code>searchMatch*</code>, <code>scrollbar*</code></td></tr><tr><td>消息</td><td><code>userMessage*</code>, <code>customMessage*</code>, <code>thinkingText</code></td></tr><tr><td>工具执行</td><td><code>toolPendingBg</code>, <code>toolSuccessBg</code>, <code>toolErrorBg</code>, <code>toolTitle</code>, <code>toolOutput</code></td></tr><tr><td>Markdown</td><td><code>md*</code></td></tr><tr><td>工具 diff</td><td><code>toolDiff*</code></td></tr><tr><td>语法高亮</td><td><code>syntax*</code></td></tr><tr><td>编辑器模式</td><td><code>thinking*</code>, <code>bashMode</code></td></tr><tr><td>HTML 导出</td><td><code>export.pageBg</code>, <code>export.cardBg</code>, <code>export.infoBg</code></td></tr></tbody></table><p>schema 是格式参考。内置主题提供了完整的取值，可以复制后调整。</p><p>五个颜色是可选的，省略时继承另一个颜色：</p><table tabindex="0"><thead><tr><th>可选颜色</th><th>回退</th></tr></thead><tbody><tr><td><code>scrollbarTrack</code></td><td><code>muted</code></td></tr><tr><td><code>scrollbarThumb</code></td><td><code>text</code></td></tr><tr><td><code>searchMatchBg</code></td><td><code>selectedBg</code></td></tr><tr><td><code>searchMatchText</code></td><td><code>text</code></td></tr><tr><td><code>thinkingMax</code></td><td><code>thinkingXhigh</code></td></tr></tbody></table><p>如果省略 <code>export</code> 颜色，Pi 从 <code>userMessageBg</code> 推导 HTML 页面和面板背景。</p><h2 id="从项目或包加载主题" tabindex="-1">从项目或包加载主题 <a class="header-anchor" href="#从项目或包加载主题" aria-label="Permalink to &quot;从项目或包加载主题&quot;">​</a></h2><p>项目主题放在 <code>.pi/themes/</code> 中。项目主题只在授予<a href="./security.html#understand-project-trust">项目信任</a>后加载。</p><p>也可以通过 <code>themes</code> 设置加载主题文件和目录，或在 Pi 包中分发。见<a href="./configuration.html">配置</a>、<a href="./settings.html#resources">设置</a>和 <a href="./packages.html">Pi 包</a>。</p><p>每个加载的主题必须名称唯一。Pi 将重复名称报告为资源冲突。</p>`,44)])])}const k=e(s,[["render",c]]);export{m as __pageData,k as default};
